package com.booksyde.service;
import com.booksyde.dto.response.CheckoutResponse; import com.booksyde.exception.BusinessException; import com.booksyde.repository.*; import com.stripe.StripeClient; import com.stripe.param.checkout.SessionCreateParams; import java.util.UUID; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class PaymentService { private final MarketplaceService marketplace; private final MarketplaceOrderRepository orders; private final MarketplaceSellerRepository sellers; private final String sandboxKey,liveKey,successUrl,cancelUrl; public PaymentService(MarketplaceService m,MarketplaceOrderRepository o,MarketplaceSellerRepository s,@Value("${booksyde.stripe.sandbox-secret-key:}")String sk,@Value("${booksyde.stripe.live-secret-key:}")String lk,@Value("${booksyde.stripe.success-url:http://localhost:5173/marketplace?payment=success}")String su,@Value("${booksyde.stripe.cancel-url:http://localhost:5173/marketplace?payment=cancel}")String cu){marketplace=m;orders=o;sellers=s;sandboxKey=sk;liveKey=lk;successUrl=su;cancelUrl=cu;} @Transactional public CheckoutResponse checkout(UUID orderId,UUID buyer){var order=marketplace.ownedOrder(orderId,buyer);if("paid".equals(order.getStatus()))throw new BusinessException("Pedido já foi pago.");var items=marketplace.orderItems(orderId);if(items.isEmpty())throw new BusinessException("Pedido sem itens.");int total=items.stream().mapToInt(i->i.getPriceCents()).sum();if(total!=order.getTotalCents())throw new BusinessException("Total do pedido inconsistente.");String key="live".equals(order.getStripeEnvironment())?liveKey:sandboxKey;if(key.isBlank())throw new BusinessException("Stripe não configurado para este ambiente.");var seller=sellers.findById(order.getSellerId()).orElse(null);String account=null;if(seller!=null)account="live".equals(order.getStripeEnvironment())?seller.getStripeLiveAccountId():seller.getStripeSandboxAccountId();var b=SessionCreateParams.builder().setMode(SessionCreateParams.Mode.PAYMENT).setSuccessUrl(successUrl).setCancelUrl(cancelUrl).setClientReferenceId(orderId.toString()).putMetadata("marketplace_order_id",orderId.toString());for(var i:items)b.addLineItem(SessionCreateParams.LineItem.builder().setQuantity(1L).setPriceData(SessionCreateParams.LineItem.PriceData.builder().setCurrency("brl").setUnitAmount((long)i.getPriceCents()).setProductData(SessionCreateParams.LineItem.PriceData.ProductData.builder().setName(i.getTitle()).build()).build()).build());try{var client=new StripeClient(key);var params=b.build();var session=(account==null||account.isBlank())?client.checkout().sessions().create(params):client.checkout().sessions().create(params,com.stripe.net.RequestOptions.builder().setStripeAccount(account).build());order.markAwaitingPayment(session.getId(),session.getUrl(),account);orders.save(order);return new CheckoutResponse(session.getUrl(),session.getId());}catch(Exception e){throw new BusinessException("Não foi possível iniciar o checkout: "+e.getMessage());}}}
